+    if (
+      key.length === AesKeyLengths.Aes256 &&
+      offsetInKey === AES_BLOCK_BYTES
+    ) {
+      // AES-256 は鍵の中間のワードにも SubWord を適用する。
+      for (let i = 0; i < WORD_BYTES; i++) {
+        word[i] = S_BOX[word[i]];
+      }
+    }
+
+    for (let i = 0; i < WORD_BYTES; i++) {
+      expanded[offset + i] = expanded[offset + i - key.length] ^ word[i];
+    }
+  }
+
+  return expanded;
+}

